const D = { energy:.7, scale:1, hue:315, speed:1, density:.5, x:.5, y:.8, pose:'cycle', style:'wildstyle', act:'battle', smear:.6, limb:.5, seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- helpers ----
const md = (a, n) => ((a % n) + n) % n;
const frc = v => v - Math.floor(v);
const clp = (v, a, b) => Math.max(a, Math.min(b, v));
const ez = t => { t = clp(t, 0, 1); return t * t * (3 - 2 * t); };
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
const sn = (tt, off) => { const f = Math.floor(tt), xq = tt - f; return (fr(f + off) * (1 - xq) + fr(f + 1 + off) * xq - .5) * 2; };
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat;
S.lastBeat = K.beat;

const u = Math.min(width, height);
const sc = u * P.scale / 320;
const bt = K.beat * P.speed;
const sub = frc(bt);
const kick = K.pulse * .6 + A.bass * .85;
const en = P.energy * (.5 + .5 * K.intensity);
const H = md(P.hue, 360);
const chalk = P.style === 'chalk', neon = P.style === 'neon', zine = P.style === 'zine';
const LL = .78 + P.limb * .5;

// ---- seed-keyed splat layout + soft sprite cache ----
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  S.splat = [];
  for (let i = 0; i < 46; i++) S.splat.push({
    a: fr(i * 3 + 1) * 6.2832, r: 70 + fr(i * 3 + 2) * 110,
    s: 3 + fr(i * 3 + 3) * 8, dh: (fr(i * 7 + 4) - .5) * 80,
    drip: fr(i * 5 + 6) > .74, ph: fr(i * 9 + 8) * 6.2832
  });
}
if (!S.spr) {
  S.spr = createGraphics(64, 64);
  S.spr.noStroke();
  for (let r = 30; r > 0; r--) { S.spr.fill(255, 6); S.spr.ellipse(32, 32, r * 2.1, r * 2.1); }
}

// ---- choreography: which move now ----
let mv = P.pose;
if (mv === 'cycle') {
  const ph = md(bt, 16);
  if (P.act === 'cypher') {
    mv = ph < 10 ? 'toprock' : ph < 14 ? 'windmill' : (K.section % 4 === 3 ? 'freeze' : 'idle');
  } else {
    mv = (K.section % 4 === 1 && ph >= 14) ? 'idle' : ph < 8 ? 'toprock' : ph < 12 ? 'windmill' : 'freeze';
  }
}

const m = { hipX:0, dy:0, crouch:.12, tilt:0, wind:null, windT:0, freeze:false, legSplit:.8,
            lL:.06, lK:.12, rL:-.06, rK:-.12, lA:.3, lB:.3, rA:-.3, rB:-.3, head:0 };

if (mv === 'toprock') {
  const s = Math.floor(md(bt, 2)) === 0 ? 1 : -1;
  const snap = ez(sub / .28);
  const load = sub > .78 ? (sub - .78) / .22 : 0;   // anticipation: pre-load before next beat
  const bounce = Math.sin(sub * Math.PI) * 7 * en;
  m.hipX = s * 9 * snap * en;
  m.dy = -bounce + load * 3 * en;
  m.crouch = .12 + load * .3 * en + kick * .08;
  m.tilt = s * .09 * snap * en;
  if (s > 0) {
    m.rL = -.55 * snap * en; m.rK = -.15 * snap; m.lL = .12 * snap; m.lK = .2;
    m.rA = -2.5 * snap * en - .2; m.rB = -.3; m.lA = .5 - .2 * snap; m.lB = .5;
  } else {
    m.lL = .55 * snap * en; m.lK = .15 * snap; m.rL = -.12 * snap; m.rK = -.2;
    m.lA = 2.5 * snap * en + .2; m.lB = .3; m.rA = -.5 + .2 * snap; m.rB = -.5;
  }
  m.head = s * .06 + kick * .1;
} else if (mv === 'windmill') {
  const pb = P.pose === 'cycle' ? md(bt, 16) - 8 : md(bt, 4);
  m.wind = pb * 6.2832 * .75 + Math.sin(pb * 2.2) * .18;
  m.windT = pb / 4;
} else if (mv === 'freeze') {
  m.freeze = true;
  m.wind = -1.85 + sn(K.t * 3.1, 51) * .05 * en + Math.sin(K.t * .9) * .05;
  m.legSplit = .95 + K.swell * .3 * en;
} else { // idle groove
  const w = Math.sin(md(bt, 2) * Math.PI);
  m.hipX = w * 6 * en;
  m.tilt = w * .05 * en;
  m.dy = -kick * 4 * en;
  m.crouch = .14 + kick * .1;
  m.lA = .35 + w * .15; m.rA = -.35 + w * .15; m.lB = .5; m.rB = -.5;
  m.lL = .05 + w * .04; m.rL = -.05 + w * .04;
  m.head = Math.sin(bt * Math.PI) * .09 * en + kick * .1 + sn(K.t * .4, 77) * .06;
}

// ---- style plumbing (multi-pass renders) ----
let PASS = 1;
function st() {
  if (PASS === 0) { stroke(H, 85, 100, 20); strokeWeight(7); noFill(); return; }
  if (PASS === 2) { stroke(0, 0, 98, 26); strokeWeight(1.4); noFill(); return; }
  if (chalk) stroke(0, 0, 94, 85);
  else if (neon) stroke(H, 80, 100, 95);
  else stroke(0, 0, zine ? 5 : 9, 100);
  strokeWeight(zine ? 4 : chalk ? 2.4 : 3);
}
function fl(h, s, b) {
  if (PASS !== 1) { noFill(); return; }
  if (chalk) fill(0, 0, 92, 9);
  else if (neon) fill(232, 45, 13, 96);
  else if (zine) fill(0, 0, 97, 100);
  else fill(h, s, b, 100);
}

// ---- body parts ----
function leg(x, y, a1, a2) {
  push(); translate(x, y); rotate(a1);
  st(); fl(md(H + 160, 360), 55, 42);
  rect(-5.5, -2, 11, 32 * LL, 5);
  translate(0, 30 * LL); rotate(a2);
  rect(-5, 0, 10, 30 * LL, 5);
  translate(0, 30 * LL);
  fl(0, 0, 96);
  rect(-6, -2, 17, 9, 3);
  if (PASS === 1) { noStroke(); fill(md(H + 20, 360), (chalk || zine) ? 0 : 75, zine ? 12 : 78, 90); rect(-6, 4, 17, 3, 1); st(); }
  pop();
}
function arm(x, y, a1, a2) {
  push(); translate(x, y); rotate(a1);
  st(); fl(H, 80, 90);
  rect(-4.5, -2, 9, 27 * LL, 5);
  translate(0, 25 * LL); rotate(a2);
  rect(-4, 0, 8, 25 * LL, 4);
  translate(0, 25 * LL);
  fl(26, 40, 88); ellipse(0, 2, 9.5, 9.5);
  pop();
}
function capHead(nod) {
  push(); rotate(nod);
  st(); fl(26, 40, 88);
  ellipse(0, -9, 23, 24);
  if (PASS === 1) {
    noStroke();
    fill(0, 0, 10, 90);
    arc(0, -4, 10, 4 + kick * 4, .25, Math.PI - .25, CHORD);
    const blink = frc(K.t * .13 + fr(5) * 2) < .05;
    fill(0, 0, 12);
    if (blink) { rect(-6.5, -12, 4.4, 1.4, 1); rect(2.1, -12, 4.4, 1.4, 1); }
    else { ellipse(-4.4, -11.5, 3, 3.6); ellipse(4.4, -11.5, 3, 3.6); }
    st();
  }
  fl(md(H + 40, 360), 88, 92);
  arc(0, -14, 24, 19, Math.PI, 6.2832, CHORD);
  rect(-17, -16, 12, 5, 2);
  pop();
}
function windBody(mm) {
  push();
  translate(0, -26);
  rotate(mm.wind);
  const spl = mm.freeze ? mm.legSplit : .8 + Math.sin(mm.windT * 12.566) * .22;
  for (let g = -1; g <= 1; g += 2) {
    push();
    translate(14, 0);
    rotate(g * spl * .5 + (mm.freeze && g > 0 ? .55 : 0));
    st(); fl(md(H + 160, 360), 55, 42);
    rect(0, -4.5, 50 * LL, 9, 5);
    fl(0, 0, 96); rect(50 * LL, -5.5, 12, 8, 3);
    pop();
  }
  st(); fl(H, 80, 90);
  ellipse(-2, 0, 46, 26);
  fl(26, 40, 88);
  push(); translate(-29, -2); rotate(-.35);
  ellipse(0, 0, 20, 21);
  fl(md(H + 40, 360), 88, 92);
  arc(0, -5, 21, 15, Math.PI, 6.2832, CHORD);
  pop();
  pop();
}
function figGeom(mm) {
  if (mm.wind != null) {
    if (mm.freeze) {
      push();
      st(); fl(H, 80, 90);
      translate(10, -34); rotate(.3);
      rect(-4.5, 0, 9, 32, 5);
      translate(0, 31); fl(26, 40, 88); ellipse(0, 3, 10, 8);
      pop();
    }
    windBody(mm);
    return;
  }
  push();
  translate(mm.hipX, mm.dy);
  rotate(mm.tilt);
  const hipY = -60 + mm.crouch * 24;
  leg(-7, hipY, mm.lL, mm.lK);
  leg(7, hipY, mm.rL, mm.rK);
  push();
  translate(0, hipY);
  st(); fl(H, 80, 90);
  beginShape(); vertex(-12, 2); vertex(12, 2); vertex(15, -36); vertex(-15, -36); endShape(CLOSE);
  if (PASS === 1 && !chalk && !zine) {
    noStroke(); fill(md(H + 180, 360), 70, 96, 95);
    rect(-2.5, -35, 5, 36); st();
  }
  arm(-14, -32, mm.lA, mm.lB);
  arm(14, -32, mm.rA, mm.rB);
  st(); fl(26, 40, 88);
  rect(-3.5, -42, 7, 7, 2);
  push(); translate(0, -42); capHead(mm.head); pop();
  pop();
  pop();
}

// ---- render ----
push();
translate(P.x * width + Math.sin(K.t * .19) * 14 * sc, P.y * height);
scale(sc);

// spray halo behind everything (breathes with beat + bass)
blendMode(ADD);
tint(H, 70, 95, chalk ? 6 : clp(9 + kick * 12 + K.swell * 5, 0, 28));
image(S.spr, -170, -270, 340, 340);
noTint();
blendMode(BLEND);

// zine starburst rays
if (zine) {
  stroke(0, 0, 8, 40 + kick * 45); strokeWeight(2);
  for (let i = 0; i < 10; i++) {
    const aa = i / 10 * 6.2832 + K.t * .05;
    const r1 = 115 + kick * 18, r2 = r1 + 24 + kick * 20;
    line(Math.cos(aa) * r1, -60 + Math.sin(aa) * r1 * .7, Math.cos(aa) * r2, -60 + Math.sin(aa) * r2 * .7);
  }
  noStroke();
}

// paint splats + drips (density-gated, seed-placed, K.t shimmer)
const nsp = Math.floor(6 + P.density * 38);
noStroke();
for (let i = 0; i < nsp; i++) {
  const q = S.splat[i];
  const wob = 1 + Math.sin(K.t * .3 + q.ph) * .12;
  const px = Math.cos(q.a + Math.sin(K.t * .07) * .1) * q.r * wob;
  const py = -55 + Math.sin(q.a) * q.r * .5 * wob;
  if (zine) fill(0, 0, 12, 55);
  else if (chalk) fill(0, 0, 92, 22);
  else if (neon) fill(md(H + q.dh, 360), 85, 100, 20);
  else fill(md(H + q.dh, 360), 80, 90, 42);
  ellipse(px, py, q.s, q.s);
  if (q.drip && !chalk) {
    const dl = 8 + (Math.sin(K.t * .21 + q.ph) * .5 + .5) * 16;
    rect(px - q.s * .12, py, q.s * .24, dl, 2);
  }
}

// wildstyle arrows orbiting the dancer
if (P.style === 'wildstyle' || zine) {
  for (let i = 0; i < 2; i++) {
    const aa = K.t * .12 + i * Math.PI;
    push();
    translate(Math.cos(aa) * 145, -70 + Math.sin(aa) * 55);
    rotate(aa + .7);
    noStroke();
    fill(zine ? 0 : md(H + 30, 360), zine ? 0 : 90, zine ? 10 : 95, 60);
    beginShape(); vertex(0, -14); vertex(12, 0); vertex(4, 0); vertex(4, 12); vertex(-4, 12); vertex(-4, 0); vertex(-12, 0); endShape(CLOSE);
    pop();
  }
}

// floor shadow
noStroke(); fill(0, 0, 0, 42);
ellipse(m.hipX * .6, 1, m.wind != null ? 120 : 72, 13);

// motion-smear arcs during windmill
if (m.wind != null && !m.freeze && P.smear > .02) {
  blendMode(ADD); noFill();
  for (let g = 1; g <= 4; g++) {
    stroke(md(H + g * 14, 360), 85, 100, clp((26 - g * 5) * P.smear * (.4 + en), 0, 30));
    strokeWeight(4 - g * .7);
    const ga = m.wind - g * .33;
    arc(0, -26, 150, 130, ga - .6, ga + .05);
    arc(0, -26, 150, 130, ga - .6 + Math.PI, ga + .05 + Math.PI);
  }
  blendMode(BLEND); noStroke();
}

// figure (style passes: neon glow pre-pass, chalk double-line after-pass)
if (neon) { PASS = 0; blendMode(ADD); figGeom(m); blendMode(BLEND); }
PASS = 1; figGeom(m);
if (chalk) { PASS = 2; push(); translate(1.5, -1.1); figGeom(m); pop(); PASS = 1; }

// treble sparkles (baseline shimmer, bloom on hats)
const spark = clp(A.treble * 1.5 + Math.max(0, K.swell - .75) * .5, 0, 1);
blendMode(ADD); noStroke();
for (let i = 0; i < 9; i++) {
  const ang = fr(i * 13 + 3) * 6.2832 + K.t * (.25 + fr(i + 40) * .4);
  const rr = 55 + fr(i * 17 + 9) * 85;
  const al = (Math.sin(K.t * (2 + fr(i) * 2.5) + i) * .5 + .5) * (10 + 48 * spark);
  fill(md(H + 50, 360), 25, 100, clp(al, 0, 55));
  const sx2 = Math.cos(ang) * rr, sy2 = -60 + Math.sin(ang) * rr * .6;
  rect(sx2 - .8, sy2 - 4, 1.6, 8, 1);
  rect(sx2 - 4, sy2 - .8, 8, 1.6, 1);
}
blendMode(BLEND);
pop();
